using System.Text;

namespace Invoicing;

/// <summary>Renders an invoice to a plain-text document.</summary>
public sealed class InvoiceRenderer
{
    public string Render(Invoice invoice, Account account)
    {
        var sb = new StringBuilder();

        sb.AppendLine($"INVOICE {invoice.Number}");
        AppendAccountDetails(sb, account);

        var (net, vat) = AppendInvoiceLines(sb, invoice);
        var discount = CalculateDiscount(net, account.Kind);
        var gross = Math.Max(0m, net + vat - discount);

        sb.AppendLine($"NET {net} VAT {vat} DISC {discount} TOTAL {gross}");
        AppendPaymentTerms(sb, account.Kind);
        return sb.ToString();
    }

    private static void AppendAccountDetails(StringBuilder sb, Account account)
    {
        if (account.Name.Length > 0)
            sb.AppendLine(account.Name);

        switch (account.Kind)
        {
            case AccountKind.Business:
                sb.AppendLine("VAT registered");
                break;
            case AccountKind.Government:
                sb.AppendLine("Government purchase order");
                break;
            case AccountKind.Consumer:
                sb.AppendLine("Consumer");
                break;
        }
    }

    private static (decimal Net, decimal Vat) AppendInvoiceLines(
        StringBuilder sb,
        Invoice invoice)
    {
        decimal net = 0m;
        decimal vat = 0m;

        foreach (var line in invoice.Lines)
        {
            if (line.NetAmount < 0m)
                continue;

            var lineVat = line.NetAmount * line.VatRate;
            AppendInvoiceLine(sb, line.Description, line.NetAmount, line.VatRate, lineVat);
            net += line.NetAmount;
            vat += lineVat;

            if (line.Description.Length > 40)
                sb.AppendLine("  (description truncated)");
        }

        return (net, vat);
    }

    private static void AppendInvoiceLine(
        StringBuilder sb,
        string description,
        decimal netAmount,
        decimal vatRate,
        decimal lineVat)
    {
        if (vatRate == 0m)
            sb.AppendLine($"{description} {netAmount} (zero-rated)");
        else if (vatRate >= 0.2m)
            sb.AppendLine($"{description} {netAmount} (std {lineVat})");
        else
            sb.AppendLine($"{description} {netAmount} (reduced {lineVat})");
    }

    private static decimal CalculateDiscount(decimal net, AccountKind accountKind)
    {
        if (net > 1000m && accountKind == AccountKind.Business)
            return net * 0.05m;
        if (net > 5000m)
            return net * 0.10m;
        return 0m;
    }

    private static void AppendPaymentTerms(StringBuilder sb, AccountKind accountKind)
    {
        sb.AppendLine(accountKind == AccountKind.Government
            ? "Remit within 30 days"
            : "Remit within 14 days");
    }
}
